/* @autogenerated */
import { Component, inject, Injector, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { Acl } from '@shared/data/acl/acl.model';
import { BaseDetailAction } from './base-detail-action';

interface Item {
  uid: string;
}

const acl = signal<{ generic: Acl } | undefined>(undefined);
const repository = {
  // Como RepositoryService.acl(): necesita contexto de inyección
  acl: () => {
    inject(Injector);
    return Object.assign(acl, { fetch: jasmine.createSpy('fetch') }) as any;
  },
};

@Component({ selector: 'test-detail-action', template: '<ng-template #formTemplate>detail</ng-template>' })
class TestDetailAction extends BaseDetailAction<Item> {
  protected readonly scope = 'test';
  protected readonly repository = repository;
}

describe('BaseDetailAction', () => {
  let action: TestDetailAction;

  beforeEach(() => {
    acl.set(undefined);
    TestBed.configureTestingModule({
      imports: [TestDetailAction, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
    const fixture = TestBed.createComponent(TestDetailAction);
    fixture.detectChanges();
    action = fixture.componentInstance;
  });

  afterEach(() => TestBed.resetTestingModule());

  it('is a contextual action named detail with a render template', () => {
    expect(action.name).toBe('detail');
    expect(action.contextual).toBeTrue();
    expect(action.render()).toBeTruthy();
  });

  it('is visible only with the retrieve permission', () => {
    expect(action.visible([{ uid: 'a' }])()).toBeFalse();

    acl.set({ generic: { allows: [{ name: 'update', allowed: true }] } });
    expect(action.visible([{ uid: 'a' }])()).toBeFalse();

    acl.set({ generic: { allows: [{ name: 'retrieve', allowed: true }] } });
    expect(action.visible([{ uid: 'a' }])()).toBeTrue();
  });
});
